According to the documentation in https://github.com/grpc/proposal/blob/37e658b12f1684f29b3acca04f0167b84d502876/A6-client-retries.md#grpc-retry-design, gRPC retries are categorized into transparent retries and non-transparent retries, which are supposed to be independent of each other. However, in my testing, I found that transparent retries seem to depend on whether non-transparent retries are enabled.

My code of grpc client is:

```go
package main

import (
	"context"
	"flag"
	"log"
	"os"
	"time"

	pb "grpc-test/proto"

	retrytracer "grpc-test/retry-tracer"

	"google.golang.org/grpc"
	"google.golang.org/grpc/backoff"
	"google.golang.org/grpc/credentials/insecure"
	"google.golang.org/grpc/grpclog"
)

var (
	addr        = flag.String("addr", "127.0.0.1:9001", "the address to connect to")
	retryPolicy = `{
		"methodConfig": [{
		  "name": [{"service": "echo.Echo","method":"UnaryEcho"}],
		  "retryPolicy": {
			  "MaxAttempts": 5,
			  "InitialBackoff": "2s",
			  "MaxBackoff": "5s",
			  "BackoffMultiplier": 2.0,
			  "RetryableStatusCodes": ["UNAVAILABLE"]
		  }
		}]}`
)

func init() {
	grpclog.SetLoggerV2(grpclog.NewLoggerV2(
		os.Stdout,
		os.Stdout,
		os.Stderr,
	))
}

func main() {
	counter := retrytracer.NewRetryCounter()
	conn, err := grpc.NewClient(
		*addr,
		grpc.WithTransportCredentials(insecure.NewCredentials()),
		grpc.WithDefaultServiceConfig(retryPolicy),
		grpc.WithStatsHandler(retrytracer.NewRetryStatsHandler(counter)),
		grpc.WithConnectParams(grpc.ConnectParams{
			Backoff: backoff.Config{
				BaseDelay:  2 * time.Second,
				Multiplier: 2.0,
				MaxDelay:   10 * time.Second,
				Jitter:     0.0,
			},
			MinConnectTimeout: 10 * time.Second,
		}),
	)
	if err != nil {
		log.Fatalf("did not connect: %v", err)
	}
	defer func() {
		if e := conn.Close(); e != nil {
			log.Printf("failed to close connection: %s", e)
		}
	}()

	c := pb.NewEchoClient(conn)

	ctx, cancel := context.WithTimeout(context.Background(), 600*time.Second)
	defer cancel()
	reply, err := c.UnaryEcho(ctx, &pb.EchoRequest{Message: "Try and Success"})
	if err != nil {
		log.Fatalf("UnaryEcho error: %v", err)
	}
	log.Printf("UnaryEcho reply: %v", reply)
}
```

And the retrytracer.go:

```go
package retrytracer

import (
	"context"
	"log"
	"sync/atomic"

	"google.golang.org/grpc/stats"
)

type RetryCounter struct {
	attempts int32
}

func NewRetryCounter() *RetryCounter {
	return &RetryCounter{}
}

func (rc *RetryCounter) Increment() {
	atomic.AddInt32(&rc.attempts, 1)
}

func (rc *RetryCounter) Reset() {
	atomic.StoreInt32(&rc.attempts, 0)
}

type RetryStatsHandler struct {
	retryCounter *RetryCounter
}

func NewRetryStatsHandler(counter *RetryCounter) *RetryStatsHandler {
	return &RetryStatsHandler{retryCounter: counter}
}

func (h *RetryStatsHandler) TagRPC(ctx context.Context, info *stats.RPCTagInfo) context.Context {
	return ctx
}

func (h *RetryStatsHandler) HandleRPC(ctx context.Context, s stats.RPCStats) {
	switch st := s.(type) {
	case *stats.Begin:

	case *stats.End:
		h.retryCounter.Increment()
		total := h.retryCounter.attempts
		log.Printf("RPC call completed, total attempts: %d, status: %v", total, st.Error)
	}
}

func (h *RetryStatsHandler) TagConn(ctx context.Context, info *stats.ConnTagInfo) context.Context {
	return ctx
}

func (h *RetryStatsHandler) HandleConn(ctx context.Context, s stats.ConnStats) {}
```

Here's my test setup and observations:

